const $=id=>document.getElementById(id);let busy=false;
async function api(path,body){const response=await fetch('/api/admin/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',credentials:'same-origin'});const data=await response.json();if(!response.ok){if(response.status===401){$('login').hidden=false;$('controls').hidden=true;}throw Error(data.error||'Request failed');}return data;}
function render(data){$('login').hidden=true;$('controls').hidden=false;const r=data.round;const seconds=r.endsAt?Math.max(0,Math.ceil((r.endsAt-data.serverTime)/1000)):0;$('round').textContent=`${r.mode==='koth'?'King of the Hill':'FFA'} · ${r.phase==='playing'?(r.endsAt?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Live'):'Ended'}`;$('details').textContent=r.king?`${r.king.name} has the crown`:'';$('players').replaceChildren(...data.players.map(p=>{const li=document.createElement('li');li.textContent=p.name+(p.ready?' · ready':' · scanning');return li;}));}
async function refresh(){if(busy||document.hidden)return;try{render(await api('state'));}catch(error){if(!$('controls').hidden||error.message.includes('ADMIN_PASSWORD'))$('error').textContent=error.message;}}
$('login').onsubmit=async event=>{event.preventDefault();busy=true;try{await api('login',{password:$('password').value});$('password').value='';$('error').textContent='';render(await api('state'));}catch(error){$('error').textContent=error.message;}finally{busy=false;}};
for(const button of document.querySelectorAll('[data-action]'))button.onclick=async()=>{if(busy)return;busy=true;for(const b of document.querySelectorAll('[data-action]'))b.disabled=true;try{render(await api('command',{action:button.dataset.action,mode:button.dataset.mode}));$('error').textContent='Broadcast sent to the arena.';}catch(error){$('error').textContent=error.message;}finally{busy=false;for(const b of document.querySelectorAll('[data-action]'))b.disabled=false;}};
$('logout').onclick=async()=>{try{await api('logout',{});$('controls').hidden=true;$('login').hidden=false;$('error').textContent='Signed out.';}catch(error){$('error').textContent=error.message;}};
void refresh();setInterval(refresh,2000);
